"""Commission calculator core.

Implements the deterministic earnings math described in
``skills/research/commission-calculator/SKILL.md`` (Steps 3-6, Output Schema).

Scope note: the skill references ``references/list-affitor-api.md`` for pulling
live program data, but that reference is absent from this repository snapshot.
This module therefore takes program details as explicit input (matching the
skill's Input Schema) and performs no network access. Fetching live program
data would be layered on top of :func:`calculate` once the API reference exists.
"""

import re

SCENARIOS = {"conservative": 0, "realistic": 1, "optimistic": 2}

# (conservative, realistic, optimistic) defaults derived from the benchmark
# tables in SKILL.md Step 3. Keyed by platform; blog is the fallback.
PLATFORM_BENCHMARKS = {
    "blog": {"ctr": (0.015, 0.03, 0.06), "cr": (0.01, 0.02, 0.05)},
    "youtube": {"ctr": (0.01, 0.03, 0.10), "cr": (0.01, 0.03, 0.06)},
    "tiktok": {"ctr": (0.005, 0.01, 0.02), "cr": (0.005, 0.01, 0.02)},
    "email": {"ctr": (0.10, 0.15, 0.20), "cr": (0.03, 0.05, 0.08)},
    "twitter": {"ctr": (0.005, 0.01, 0.02), "cr": (0.005, 0.01, 0.02)},
}

RECURRING_TYPE = "cps_recurring"


def commission_per_sale(reward_value, reward_type=None, avg_product_price=None):
    """Commission earned per conversion.

    Percentage rewards (e.g. ``"30%"``) require ``avg_product_price``; fixed
    rewards (e.g. ``"$50"`` or ``50``) are returned as-is.
    """
    rv = str(reward_value).strip()
    if rv.endswith("%"):
        pct = float(rv[:-1].strip())
        if avg_product_price is None:
            raise ValueError(
                "avg_product_price is required for percentage-based reward_value"
            )
        return round(float(avg_product_price) * pct / 100.0, 2)
    return round(float(rv.replace("$", "").replace(",", "").strip()), 2)


def duration_to_months(reward_duration):
    """Map a ``reward_duration`` string to a month count.

    ``None`` means an unbounded (lifetime) payout. "First purchase only" is
    functionally one-time, so it maps to a single month.
    """
    if reward_duration is None:
        return None
    s = str(reward_duration).lower()
    if "lifetime" in s:
        return None
    if "first" in s:
        return 1
    m = re.search(r"(\d+)", s)
    return int(m.group(1)) if m else None


def project_monthly_revenue(conversions_per_month, per_sale, reward_type,
                            month, duration_months=None):
    """Revenue in a given ``month`` (1-indexed) for a fixed acquisition rate.

    Recurring rewards compound: every prior cohort that is still within its
    payout window keeps paying. Non-recurring rewards pay once, so revenue is
    flat at ``conversions_per_month * per_sale``.
    """
    if reward_type == RECURRING_TYPE:
        if duration_months is None:
            active_cohorts = month
        else:
            active_cohorts = min(month, duration_months)
        return round(active_cohorts * conversions_per_month * per_sale, 2)
    return round(conversions_per_month * per_sale, 2)


def _parse_amount(text):
    """Extract the first number from a string like ``"$500/mo"`` -> ``500.0``."""
    if text is None:
        return None
    if isinstance(text, (int, float)):
        return float(text)
    m = re.search(r"(\d+(?:\.\d+)?)", str(text).replace(",", ""))
    return float(m.group(1)) if m else None


def calculate(payload):
    """Run the calculator over the skill's Input Schema, return Output Schema."""
    scenario = payload.get("scenario", "realistic")
    if scenario not in SCENARIOS:
        raise ValueError("unknown scenario: %r" % scenario)
    idx = SCENARIOS[scenario]

    platform = payload.get("platform", "blog")
    bench = PLATFORM_BENCHMARKS.get(platform, PLATFORM_BENCHMARKS["blog"])

    traffic = payload.get("traffic") or {}
    visitors = (
        traffic.get("monthly_visitors")
        or traffic.get("email_subscribers")
        or traffic.get("social_followers")
        or 0
    )

    # Explicit overrides let callers model buyer-intent traffic (SKILL Step 3).
    ctr = payload.get("ctr", bench["ctr"][idx])
    cr = payload.get("conversion_rate", bench["cr"][idx])
    conversions = visitors * ctr * cr

    goal = _parse_amount(payload.get("goal"))

    projections = []
    for prog in payload["programs"]:
        rt = prog.get("reward_type")
        per_sale = commission_per_sale(
            prog["reward_value"], rt, prog.get("avg_product_price")
        )
        dur = duration_to_months(prog.get("reward_duration"))

        monthly_30d = project_monthly_revenue(conversions, per_sale, rt, 1, dur)
        monthly_90d = project_monthly_revenue(conversions, per_sale, rt, 3, dur)
        monthly_12m = project_monthly_revenue(conversions, per_sale, rt, 12, dur)
        cumulative_12m = round(
            sum(
                project_monthly_revenue(conversions, per_sale, rt, n, dur)
                for n in range(1, 13)
            ),
            2,
        )

        sales_needed = visitors_needed = None
        if goal is not None and per_sale > 0:
            sales_needed = round(goal / per_sale, 2)
            if ctr * cr > 0:
                visitors_needed = int(round(sales_needed / (ctr * cr)))

        projections.append({
            "program_name": prog["name"],
            "reward_type": rt,
            "commission_per_sale": per_sale,
            "monthly_30d": monthly_30d,
            "monthly_90d": monthly_90d,
            "monthly_12m": monthly_12m,
            "cumulative_12m": cumulative_12m,
            "sales_needed_for_goal": sales_needed,
            "visitors_needed_for_goal": visitors_needed,
        })

    top_program = None
    if projections:
        top_program = max(projections, key=lambda p: p["cumulative_12m"])[
            "program_name"
        ]

    return {
        "output_schema_version": "1.0.0",
        "projections": projections,
        "assumptions": {
            "monthly_visitors": visitors,
            "ctr": ctr,
            "conversion_rate": cr,
            "scenario": scenario,
            "avg_product_price": (
                payload["programs"][0].get("avg_product_price")
                if payload.get("programs")
                else None
            ),
        },
        "top_program": top_program,
        "insight": _insight(projections, top_program),
    }


def _insight(projections, top_program):
    if not projections:
        return "No programs supplied."
    top = max(projections, key=lambda p: p["cumulative_12m"])
    kind = "recurring" if top["reward_type"] == RECURRING_TYPE else "one-time"
    return (
        "%s leads at ~$%.2f in year-one commissions (%s). Projections assume "
        "steady traffic; real first sales often lag 2-3 months."
        % (top_program, top["cumulative_12m"], kind)
    )
